data class Point(val x: Int, val y: Int)

fun distance(a: Point, b: Point): Double {
    val dx = (a.x - b.x).toDouble()
    val dy = (a.y - b.y).toDouble()
    return Math.sqrt(dx * dx + dy * dy)
}

