void reverse(char *str) {
    int n = strlen(str);
    for (int i = 0; i < n / 2; i++) {
        char tmp = str[i];
        str[i] = str[n - 1 - i];
        str[n - 1 - i] = tmp;
    }
}

int main() {
    char s[] = "hello";
    reverse(s);
    printf("%s\n", s);
    return 0;
}

