fn bubble_sort(arr: &mut Vec<i32>) {
    let n = arr.len();
    for i in 0..n {
        for j in 0..n - 1 - i {
            if arr[j] > arr[j + 1] {
                arr.swap(j, j + 1);
            }
        }
    }
}

fn main() {
    let mut v = vec![5, 2, 8, 1, 9];
    bubble_sort(&mut v);
    println!("{:?}", v);
}

type Stack<T> = {
  items: T[];
  push: (item: T) => void;
  pop: () => T | undefined;
};

function createStack<T>(): Stack<T> {
  const items: T[] = [];
  return {
    items,
    push: (item) => items.push(item),
    pop: () => items.pop(),
  };
}

