bool isBalanced(const std::string& s) {
    std::stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '[') st.push(c);
        else if (c == ')' && (st.empty() || st.top() != '(')) return false;
        else if (c == ']' && (st.empty() || st.top() != '[')) return false;
        else st.pop();
    }
    return st.empty();
}

int main() {
    std::cout << isBalanced("([])([)]") << std::endl;
    return 0;
}

