  def quicksort(lst: List[Int]): List[Int] = lst match {
    case Nil => Nil
    case head :: tail =>
      val smaller = tail.filter(_ <= head)
      val bigger  = tail.filter(_ > head)
      quicksort(smaller) ::: head :: quicksort(bigger)
  }

  println(quicksort(List(3, 1, 4, 1, 5, 9, 2, 6)))
}

class Node:
    def __init__(self, val):
        self.val = val
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, val):
        node = Node(val)
        if not self.head:
            self.head = node
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = node

    def to_list(self):
        result, cur = [], self.head
        while cur:
            result.append(cur.val)
            cur = cur.next
        return result

